/* eslint-disable import/no-nodejs-modules, typescript-eslint/no-unsafe-argument, typescript-eslint/no-unsafe-assignment, typescript-eslint/no-unsafe-call, typescript-eslint/no-unsafe-member-access, typescript-eslint/no-unsafe-return, typescript-eslint/strict-boolean-expressions -- Untyped Node script that spawns pnpm and Playwright. */
// Runs the extension's local-backend E2E suite.
// Ports come from `pnpm dev:status --json` through the validating resolver.
// Nothing generated by the resolver is handed to a shell.
// Manual run: pnpm --filter kilo-extension e2e:local
import { spawnSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseDevStatus, resolveE2ePorts } from './resolve-e2e-ports.mjs';

const EXTENSION_DIR = join(dirname(fileURLToPath(import.meta.url)), '..');
const PLAYWRIGHT_TESTS = [
  'tests/e2e/local-backend-live.test.ts',
  'tests/e2e/agents-mode-live.test.ts',
];

const fail = message => {
  process.stderr.write(`e2e:local: ${message}\n`);
  process.exit(1);
};

const run = (command, args, env) => {
  const result = spawnSync(command, args, { cwd: EXTENSION_DIR, env, stdio: 'inherit' });
  if (result.error) {
    fail(`${command} could not start: ${result.error.message}`);
  }
  if (result.status !== 0) {
    process.exit(result.status ?? 1);
  }
};

const main = () => {
  const status = spawnSync('pnpm', ['-s', '-w', 'dev:status', '--json'], {
    cwd: EXTENSION_DIR,
    encoding: 'utf8',
    maxBuffer: 8 * 1024 * 1024,
  });
  if (status.error) {
    fail(`dev:status could not start: ${status.error.message}`);
  }
  if (status.stderr) {
    process.stderr.write(status.stderr);
  }
  if (status.status !== 0) {
    fail(`dev:status exited with status ${String(status.status)}`);
  }

  const payload = parseDevStatus(status.stdout);
  if (payload === null) {
    fail('dev:status did not print JSON');
  }

  const env = {
    ...process.env,
    ...resolveE2ePorts(payload, process.env),
    EXTENSION_LOCAL_BACKEND_E2E: '1',
  };

  run('pnpm', ['run', 'build'], env);
  run(
    'pnpm',
    ['exec', 'playwright', 'test', '-c', 'playwright.config.ts', ...PLAYWRIGHT_TESTS],
    env
  );
};

main();
